//! Code generated by `gravenc` (via `build.rs`, from `schemas/*.graven` and the committed
//! locks) for `bank`, `game`, `iot`, `stream` and the `evo` evolution fixtures.
//! The support it depends on lives in the runtime, `graven::rt`; the docs of
//! `graven::rt` describe the frozen pattern and the "Invariants for the code generator".
//!
//! Each generated file is the only content of its module (the safety rule in
//! `docs/graven-language.md`): neighboring code could construct `XVerified(...)` without
//! `verify()`.
//!
//! `unsafe` is denied in the whole crate. The only exceptions are generated items with their
//! own `#[allow(unsafe_code)]` that *call* fixed-contract `unsafe` functions of the
//! runtime, each with a `// SAFETY:` comment citing the invariant.
#![deny(unsafe_code)]

/// `schemas/bank.graven`. The verified view cannot be constructed outside the generated module:
/// ```compile_fail,E0603
/// let buf = [0u8; 64];
/// let t = graven_schemas::bank::Transaction::read(&buf).unwrap();
/// let v = graven_schemas::bank::TransactionVerified(t);
/// ```
pub mod bank {
    include!(concat!(env!("OUT_DIR"), "/bank.rs"));
}
pub mod game {
    include!(concat!(env!("OUT_DIR"), "/game.rs"));
}
pub mod iot {
    include!(concat!(env!("OUT_DIR"), "/iot.rs"));
}
pub mod stream {
    include!(concat!(env!("OUT_DIR"), "/stream.rs"));
}

/// Evolution fixtures of `bank.graven` (same namespace `bank`; only `Transaction` changes):
///
/// - v2 (`schemas/evo/bank_v2.graven`): `fee @7: i64?` added; `note @6` reserved;
///   `from_shard @3` became `u32?`.
/// - v3 (`schemas/evo/bank_v3.graven`): v2 + `to_shard @4` reserved (it was required:
///   confirmed with `#[allow_breaking_readers]`).
///
/// Each version is a complete schema, so it has its own `Currency`/`Entry`.
pub mod evo {
    pub mod bank_v2 {
        include!(concat!(env!("OUT_DIR"), "/bank_v2.rs"));
    }
    pub mod bank_v3 {
        include!(concat!(env!("OUT_DIR"), "/bank_v3.rs"));
    }
}

pub use graven::rt::*;
